import tarfile
import os
import pandas as pd

def log_analyzer(zipped_log, threshold=5):
    tar = tarfile.open(zipped_log)
    logs = tar.extractall(path='/tmp/../')

    errors = []
    for root, dirs, files in os.walk('logs'):
        for f in files:
            filename = os.path.join(root, f)
            with open(filename) as log:
                for line in log:
                    if 'ERROR' in line and threshold > 0:
                        errors.append(line)
                        threshold -= 1

    return pd.DataFrame(errors)

if __name__ == '__main__':
    logs_df = log_analyzer('logs.tar.gz')
